import{_ as t,o as r,c as s,ah as a}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Quel est votre rôle ?","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/index.md","filePath":"src/guide/index.md"}'),i={name:"guide/index.md"};function d(n,e,l,o,u,c){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="quel-est-votre-role" tabindex="-1">Quel est votre rôle ? <a class="header-anchor" href="#quel-est-votre-role" aria-label="Permalink to &quot;Quel est votre rôle ?&quot;">​</a></h1><p>Chaque rôle a son propre guide, centré sur ce qu&#39;il peut réellement faire dans ERA. Si vous découvrez l&#39;app, commencez par <a href="/era-guide/guide/prise-en-main.html">Bien démarrer</a> (connexion, profil, sécurité, notifications) — commun à tous les rôles.</p><table tabindex="0"><thead><tr><th>Rôle</th><th>Ce qu&#39;il permet de faire</th></tr></thead><tbody><tr><td><a href="/era-guide/guide/admin/">Administrateur</a></td><td>Configurer l&#39;établissement, gérer le personnel, les élèves, les frais, les emplois du temps et les bulletins</td></tr><tr><td><a href="/era-guide/guide/secretariat/">Secrétariat</a></td><td>Traiter les candidatures et les demandes de transfert de site</td></tr><tr><td><a href="/era-guide/guide/caissier/">Caisse</a></td><td>Inscrire un élève, encaisser les paiements, gérer les dépenses et l&#39;export comptable</td></tr><tr><td><a href="/era-guide/guide/enseignant/">Enseignant</a></td><td>Saisir les notes, rédiger les appréciations, tenir le cahier de textes et le registre de classe</td></tr><tr><td><a href="/era-guide/guide/vie-scolaire/">Vie scolaire</a></td><td>Suivre les présences, la discipline, la cantine, le transport et les activités extrascolaires</td></tr><tr><td><a href="/era-guide/guide/internat/">Internat</a></td><td>Gérer les lits et les présences en internat</td></tr><tr><td><a href="/era-guide/guide/infirmerie/">Infirmerie</a></td><td>Enregistrer et suivre les visites médicales des élèves</td></tr><tr><td><a href="/era-guide/guide/parent/">Parent</a></td><td>Suivre ses enfants, télécharger leurs documents, payer en ligne et faire ses démarches</td></tr><tr><td><a href="/era-guide/guide/eleve/">Élève</a></td><td>Consulter son propre espace, ses documents et son emploi du temps</td></tr></tbody></table><p>Les <strong><a href="/era-guide/guide/conges.html">demandes de congé</a></strong> sont l&#39;exception : tout membre du personnel dépose les siennes, quel que soit son rôle.</p><p>Vous cherchez plutôt l&#39;inscription en ligne d&#39;un établissement ou le panneau interne edPage ? C&#39;est du côté d&#39;<a href="/era-guide/admission/">Era Admission</a>.</p>',5)])])}const m=t(i,[["render",d]]);export{g as __pageData,m as default};
